//! 🧪️ Actual allocation and post failures keep their original owner.
use super::*;
use crate::native_decoding::NativeAllocationEvent;
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};
fn close<T:crate::retirement::RetireOwned>(value:T){let grant=crate::RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).ok().unwrap();while !owner.terminal_is_empty(){let mut actual=None;let mut effect=crate::RetainedAllocationEffect::new(grant,u64::MAX,&mut actual);let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.step(&mut effect));result.unwrap();assert_eq!(heap.0,actual.unwrap_or(0));}}
struct ActualPort<F>(F);
impl<F:FnMut(NativeAllocationEvent)->Result<(),crate::NativeAllocationRefusal>> crate::NativeAllocationAuthorityPort for ActualPort<F>{
 type Context<'turn,'source>=() where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError> where 'source:'turn{Ok(())}
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn receive<'reply,'turn,'source>(&mut self,_:&mut (),event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let result=(||->Result<(),crate::NativeAllocationRefusal>{(self.0)(event)})();Ok(reply.complete(result))}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut (),_:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let result=(||->Result<Option<Result<(),crate::NativeAllocationRefusal>>,ValueError>{Ok(None)})()?;Ok(match result{Some(verdict)=>reply.complete(verdict),None=>reply.pending()})}
}
#[test]
fn slot_posts_real_allocator_failure_and_retains_post_refusal(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let case=fixture["allocationSettlement"].as_array().unwrap().iter().find(|row|row["name"]=="allocationAndPostRefused").unwrap();let prior=case["prior"].as_u64().unwrap()as usize;let request=case["requested"].as_u64().unwrap()as usize;let admitted=AtomicUsize::new(0);let posted=AtomicUsize::new(usize::MAX);let deny=AtomicBool::new(false);let mut port=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(quote)=>{assert_eq!(quote.owned_bytes,admitted.load(Ordering::Relaxed));Ok(())},NativeAllocationEvent::Post{request,actual}=>{admitted.store(request.next_owned_bytes,Ordering::Relaxed);posted.store(actual,Ordering::Relaxed);if deny.load(Ordering::Relaxed){Err(ValueError::literal(ValueRefusalKind::Canceled,"post refused").into())}else{Ok(())}},NativeAllocationEvent::Cancel(_)=>if deny.load(Ordering::Relaxed){Err(ValueError::literal(ValueRefusalKind::Canceled,"cancel refused").into())}else{Ok(())}};let mut authority=crate::NativeAllocationAuthority::new(ActualPort(port));authority.with_send_loan(&mut (),|loan|{let mut progress=|_|true;let mut native=NativeDecodeControl::new_forwarded(prior+request,&mut progress,loan);let mut prior_owner=Vec::<u8>::new();let mut unwind=None;let mut prior_actual=None;native.allocate_vec_into(prior,&mut prior_owner,&mut prior_actual,&mut unwind).unwrap();deny.store(true,Ordering::Relaxed);let mut output=Vec::<u8>::new();let mut actual=None;let((result,attempts),physical)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||native.allocate_vec_into(request,&mut output,&mut actual,&mut unwind)));let failure=result.unwrap_err();assert_eq!(attempts,1);assert_eq!(physical,(0,0));assert_eq!(failure.primary.as_ref().unwrap().kind,ValueRefusalKind::AllocationFailed);assert_eq!(failure.forwarded_post.as_ref().unwrap().owned().unwrap().message.as_ref(),"post refused");assert_eq!(actual,Some(0));assert_eq!(prior_actual,Some(prior));assert_eq!(failure.progress.actual_capacity_bytes,Some(0));assert_eq!(failure.progress.admitted_bytes,prior+request);assert_eq!(native.owned_bytes(),prior+request);assert_eq!(admitted.load(Ordering::Relaxed),prior+request);assert_eq!(posted.load(Ordering::Relaxed),0);assert!(output.is_empty());assert_eq!(output.capacity(),0);assert!(unwind.is_none());drop(native);close(prior_owner);close(output);close(failure);}).unwrap();assert!(authority.into_port().is_ok());
}
#[test]
fn slot_retains_born_owner_when_original_post_refuses(){
 let mut port=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(_)=>Ok(()),NativeAllocationEvent::Post{..}=>Err(ValueError::literal(ValueRefusalKind::Canceled,"post refused").into()),NativeAllocationEvent::Cancel(_)=>panic!("unexpected cancellation")};let mut authority=crate::NativeAllocationAuthority::new(ActualPort(port));authority.with_send_loan(&mut (),|loan|{let mut progress=|_|true;let mut native=NativeDecodeControl::new_forwarded(5,&mut progress,loan);let mut output=Vec::<u8>::new();let mut unwind=None;let mut actual=None;let failure=native.allocate_vec_into(5,&mut output,&mut actual,&mut unwind).unwrap_err();assert_eq!(output.capacity(),5);assert_eq!(failure.progress.actual_capacity_bytes,Some(output.capacity()));assert_eq!(failure.progress.admitted_bytes,5);assert_eq!(failure.forwarded_post.as_ref().unwrap().owned().unwrap().message.as_ref(),"post refused");assert!(unwind.is_none());drop(native);close(output);close(failure);}).unwrap();assert!(authority.into_port().is_ok());
}

#[test]
fn text_slot_retains_original_backing_on_post_refusal(){
 let mut port=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(_)=>Ok(()),NativeAllocationEvent::Post{..}=>Err(ValueError::literal(ValueRefusalKind::Canceled,"text post refused").into()),NativeAllocationEvent::Cancel(_)=>panic!("unexpected cancellation")};let mut authority=crate::NativeAllocationAuthority::new(ActualPort(port));authority.with_send_loan(&mut (),|loan|{let mut progress=|_|true;let mut native=NativeDecodeControl::new_forwarded(5,&mut progress,loan);let mut output=String::new();let mut unwind=None;let mut actual=None;let failure=native.reserve_text_into(5,&mut output,&mut actual,&mut unwind).unwrap_err();assert!(output.is_empty());assert_eq!(output.capacity(),5);assert_eq!(failure.progress.actual_capacity_bytes,Some(output.capacity()));assert_eq!(failure.forwarded_post.as_ref().unwrap().owned().unwrap().message.as_ref(),"text post refused");assert!(unwind.is_none());drop(native);close(output);close(failure);}).unwrap();assert!(authority.into_port().is_ok());
}

struct InterruptPort{admit:bool,saved:Option<(NativeAllocationEvent,Result<(),crate::NativeAllocationRefusal> )>}
impl crate::NativeAllocationAuthorityPort for InterruptPort{
 type Context<'turn,'source>=() where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError> where 'source:'turn{Ok(())}
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn receive<'reply,'turn,'source>(&mut self,_:&mut (),event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let result=(||->Result<(),crate::NativeAllocationRefusal>{match event{NativeAllocationEvent::Quote(_)=>Ok(()),NativeAllocationEvent::Post{..} if !self.admit=>{self.saved=Some((event,Err(ValueError::literal(ValueRefusalKind::Canceled,"original post refusal").into())));panic!("original post interrupted")},NativeAllocationEvent::Admit(_) if self.admit=>{self.saved=Some((event,Err(ValueError::literal(ValueRefusalKind::Canceled,"original admission refused").into())));panic!("original admission interrupted")},_=>panic!("unexpected original allocation event")}})();Ok(reply.complete(result))}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut (),event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let result=(||->Result<Option<Result<(),crate::NativeAllocationRefusal>>,ValueError>{if self.saved.as_ref().is_some_and(|(original,_)|*original!=event){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation event changed"))}Ok(self.saved.take().map(|(_,verdict)|verdict))})()?;Ok(match result{Some(verdict)=>reply.complete(verdict),None=>reply.pending()})}
}
#[test]
fn caller_slot_and_original_callback_phase_survive_post_unwind(){let mut authority=crate::NativeAllocationAuthority::new(InterruptPort{admit:false,saved:None});authority.with_send_loan(&mut (),|loan|{let mut observe=|_|true;let mut native=NativeDecodeControl::new_forwarded(5,&mut observe,loan);let mut output=Vec::<u8>::new();let mut actual=None;let mut state=None;let unwind=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.allocate_vec_into(5,&mut output,&mut actual,&mut state)));assert!(unwind.is_err());assert_eq!(output.capacity(),5);assert_eq!(actual,Some(5));let owner=state.take().unwrap();assert!(!crate::retirement::RetireOwned::retirement_ready(&owner));let gate=crate::retirement::RetireOwned::retirement_seed(owner);state=Some(match gate.into_pending(){Ok(owner)=>owner,Err(_)=>panic!("pending original owner was lost")});let pending=state.as_mut().unwrap();assert!(native.recover_allocation_callback(pending).unwrap());native.settle_allocation_progress(pending,actual).unwrap();assert!(native.settle_allocation_progress(pending,actual).is_err());let failure=state.take().unwrap().into_outcome().ok().unwrap().into_allocation_failure(0).unwrap();assert_eq!(failure.forwarded_post.as_ref().unwrap().owned().unwrap().message.as_ref(),"original post refusal");assert_eq!(failure.progress.admitted_bytes,5);assert_eq!(failure.progress.actual_capacity_bytes,actual);drop(native);close(output);close(failure);}).unwrap();assert!(authority.into_port().is_ok());}
#[test]
fn admission_recovers_interrupted_original_verdict(){let mut authority=crate::NativeAllocationAuthority::new(InterruptPort{admit:true,saved:None});authority.with_send_loan(&mut (),|loan|{let mut observer=|_|true;let mut control=NativeDecodeControl::new_forwarded(5,&mut observer,loan);let mut slot=None;let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||control.begin_admission(5,&mut slot)));assert!(result.is_err());let state=slot.as_mut().unwrap();assert_eq!(state.phase(),crate::native_decoding::NativeDecodeAdmissionPhase::Started);assert!(control.recover_admission(state).unwrap());let failure=control.finish_admission(&mut slot).unwrap_err();assert_eq!(control.owned_bytes(),0);assert_eq!(failure.progress.actual_capacity_bytes,None);assert_eq!(failure.forwarded_admission.as_ref().unwrap().owned().unwrap().message.as_ref(),"original admission refused");assert!(slot.is_none());drop(control);close(failure);}).unwrap();assert!(authority.into_port().is_ok());}

#[test]
fn retained_original_refusal_blocks_outcome_retirement(){let mut vault=crate::NativeAllocationRefusalVault::default();let handle=vault.retain(ValueError::literal(ValueRefusalKind::Canceled,"original refused")).unwrap();let mut outcome=crate::native_decoding::NativeDecodeAllocationOutcome{request:None,admitted:false,primary:None,quote_refusal:Some(crate::NativeAllocationRefusal::Retained(handle)),extent_refusal:None,settlement_refusal:None,actual:None};assert!(!crate::retirement::RetireOwned::retirement_ready(&outcome));let handle=match outcome.quote_refusal.take().unwrap(){crate::NativeAllocationRefusal::Retained(handle)=>handle,_=>panic!("expected original retained handle")};let original=vault.take(handle).unwrap();assert_eq!(original.message.as_ref(),"original refused");assert!(crate::retirement::RetireOwned::retirement_ready(&outcome));close(outcome);close(original);}
